import{_ as e,o as i,c as t,aw as s}from"./chunks/framework.DLufY-ao.js";const h=JSON.parse('{"title":"Виды задач","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/js/event-loop/main/tasks.md","filePath":"wiki/dev-commit/js/event-loop/main/tasks.md"}'),l={name:"wiki/dev-commit/js/event-loop/main/tasks.md"};function o(r,a,n,c,m,k){return i(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="виды-задач" tabindex="-1">Виды задач <a class="header-anchor" href="#виды-задач" aria-label="Permalink to &quot;Виды задач&quot;">​</a></h1><h3 id="_1-microtasks" tabindex="-1">1. Microtasks <a class="header-anchor" href="#_1-microtasks" aria-label="Permalink to &quot;1. Microtasks&quot;">​</a></h3><p>Очередь микрозадач / задания &quot;jobs&quot; (выполняются все)</p><ul><li>Каждый раз после таски</li><li>Каждый раз когда пустеет стек</li><li>Могут выполняться посередине таска, если очистился стек</li><li>Рекурсивный вызов блокирует Event Loop</li><li>Promise.then - микротаск then. Promise.then.then - 2 микротаска</li><li>Сначала выполняется microtasks, затем tasks</li><li>Если что-то выполняется, то выполняется 1 раз</li><li>Затем происходит цикл рендеринга</li><li>Если появляется что-то еще, оно планируется</li><li>Promises process.nextTick Object.observe Mutation Observer</li></ul><h3 id="_2-render-tasks-animation-callbacks" tabindex="-1">2. Render Tasks (Animation Callbacks) <a class="header-anchor" href="#_2-render-tasks-animation-callbacks" aria-label="Permalink to &quot;2. Render Tasks (Animation Callbacks)&quot;">​</a></h3><ul><li>Задачи от Render оптимизируются браузером и, если он посчитает, что в этом цикле не нужно ничего перерисовывать, то Event Loop просто пойдет дальше</li><li>Вся запланированная очередь выполняется разом</li><li>Все остальное планируется на следующий раз и добавляется сверху на следующий фрейм</li><li>requestAnimationFrame Style Recalculate Layout Paint I/O Рендеринг пользовательского интерфейса</li></ul><h3 id="_3-macrotask-tasks" tabindex="-1">3. Macrotask (Tasks) <a class="header-anchor" href="#_3-macrotask-tasks" aria-label="Permalink to &quot;3. Macrotask (Tasks)&quot;">​</a></h3><p>Очередь задач (выполняются по одной)</p><ul><li>Выполняют всё по очереди, даже если есть что-то, что добавлено было сверху</li><li>Браузер может рендерить в промежутках между ними</li><li>Если скорость обработки равна скорости их добавления, то это бесконечный цикл и Event Loop ничего не может сделать, пока не закончатся микротаски</li><li>Поэтому микротаски блокируют рендеринг</li><li>setTimeout setInterval setImmediate AJAX</li></ul><hr>',10)])])}const _=e(l,[["render",o]]);export{h as __pageData,_ as default};
